package org.pestinha.android;
import android.content.*;import android.view.*;import java.lang.reflect.Proxy;import java.util.concurrent.atomic.AtomicInteger;import org.json.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,manifest=Config.NONE)
public class CareAndNewsTest {
 @Test public void newsDismissDoesNotOpenAndReadIsExplicit(){Context c=RuntimeEnvironment.getApplication();WindowManager wm=(WindowManager)Proxy.newProxyInstance(WindowManager.class.getClassLoader(),new Class[]{WindowManager.class},(o,m,a)->null);PetWorld world=new PetWorld(c,wm,value->{});world.bounds(360,780);AtomicInteger opened=new AtomicInteger();world.messageAction("Manchete",false,50,300,()->{},"Ler notícia",opened::incrementAndGet);world.bubble.performClick();assertEquals(0,opened.get());assertNull(world.bubble);world.messageAction("Manchete",false,50,300,()->{},"Ler notícia",opened::incrementAndGet);world.bubble.findViewWithTag("message_close").performClick();assertEquals(0,opened.get());world.messageAction("Manchete",false,50,300,()->{},"Ler notícia",opened::incrementAndGet);world.bubble.findViewWithTag("message_action").performClick();assertEquals(1,opened.get());world.close();}
 @Test public void appearanceIsSeparateAndCannotChangeIdentity() throws Exception {Context c=RuntimeEnvironment.getApplication();c.getSharedPreferences("appearance_luna",0).edit().putString("moldura","#123456").putString("item","oculos").commit();assertEquals("#123456",Characters.appearance(c,"luna").getString("moldura"));assertTrue(Characters.appearance(c,"luna").getJSONObject("acessorios").has("oculos"));assertNotEquals("#123456",Characters.appearance(c,"mimir").getString("moldura"));assertEquals(15485863,Characters.definition(c,"luna").getInt("seed"));assertEquals("Presidente",Characters.name(c,"lula"));}
 @Test public void typedLocalFunctionsRequireConsentAndRejectUnknownActions() throws Exception {try{LocalFunctions.request(new LocalFunctions.Rules(),new JSONObject(),false);fail();}catch(IllegalStateException expected){}assertEquals("feed",LocalFunctions.request(new LocalFunctions.Rules(),new JSONObject().put("hunger",.8),true).action);LocalFunctions.Provider bad=new LocalFunctions.Provider(){public String id(){return "test";}public LocalFunctions.Suggestion suggest(JSONObject c){return new LocalFunctions.Suggestion("execute_shell","bad");}};try{LocalFunctions.request(bad,new JSONObject(),true);fail();}catch(IllegalArgumentException expected){}}
}
